//! Isolated SMTC publisher -> production media reader -> lyric DLL -> native Go
//! worker -> direct online sources -> production display frame. No user commands.
use std::{path::PathBuf,time::{Duration,Instant}};
use serde_json::{json,Value};
use dotisle_music::runtime::Backend;
use windows::{core::{factory,w,HSTRING},Foundation::TimeSpan,Media::{SystemMediaTransportControls,SystemMediaTransportControlsTimelineProperties,MediaPlaybackType,MediaPlaybackStatus},Win32::{System::WinRT::{RoInitialize,RO_INIT_MULTITHREADED,ISystemMediaTransportControlsInterop},UI::WindowsAndMessaging::*}};
struct Publisher{controls:SystemMediaTransportControls,hwnd:windows::Win32::Foundation::HWND}
impl Drop for Publisher{fn drop(&mut self){let _=self.controls.SetIsEnabled(false);unsafe{let _=DestroyWindow(self.hwnd);}}}
fn wait(b:&Backend,title:&str,seconds:f64,timeout:u64)->Result<Value,String>{let until=Instant::now()+Duration::from_secs(timeout);loop{let s=b.snapshot(u64::MAX);if s["track"]["title"]==title&&s["lyricSource"].is_string()&&s["frame"]["currentLine"].as_str().is_some_and(|s|!s.is_empty()&&s!="正在检索歌词…"&&s!="暂未找到歌词")&&s["positionSeconds"].as_f64().is_some_and(|v|(v-seconds).abs()<1.){return Ok(s)}if Instant::now()>until{return Err(format!("online media pipeline timeout: {s}"))}std::thread::sleep(Duration::from_millis(60));}}
fn main()->Result<(),Box<dyn std::error::Error>>{unsafe{
 RoInitialize(RO_INIT_MULTITHREADED)?;let out=PathBuf::from(std::env::args().nth(1).ok_or("output directory required")?);std::fs::create_dir_all(&out)?;
 let hwnd=CreateWindowExW(WINDOW_EX_STYLE::default(),w!("STATIC"),w!("DotIsle isolated online fixture"),WS_OVERLAPPED,0,0,50,50,None,None,None,None)?;
 let interop:ISystemMediaTransportControlsInterop=factory::<SystemMediaTransportControls,ISystemMediaTransportControlsInterop>()?;let controls:SystemMediaTransportControls=interop.GetForWindow(hwnd)?;let p=Publisher{controls,hwnd};p.controls.SetIsEnabled(true)?;p.controls.SetIsPlayEnabled(true)?;p.controls.SetIsPauseEnabled(true)?;
 let display=p.controls.DisplayUpdater()?;display.SetType(MediaPlaybackType::Music)?;let music=display.MusicProperties()?;
 let timeline=|seconds:i64,duration:i64|->windows::core::Result<()>{let t=SystemMediaTransportControlsTimelineProperties::new()?;t.SetStartTime(TimeSpan{Duration:0})?;t.SetEndTime(TimeSpan{Duration:duration*10000000})?;t.SetMinSeekTime(TimeSpan{Duration:0})?;t.SetMaxSeekTime(TimeSpan{Duration:duration*10000000})?;t.SetPosition(TimeSpan{Duration:seconds*10000000})?;p.controls.UpdateTimelineProperties(&t)};
 music.SetTitle(&HSTRING::from("晴天"))?;music.SetArtist(&HSTRING::from("周杰伦"))?;display.Update()?;timeline(60,269)?;p.controls.SetPlaybackStatus(MediaPlaybackStatus::Paused)?;
 let b=Backend::new(json!({"AllowedSources":["verify_online_pipeline"],"IgnoredSources":[],"LocalFolders":[],"OnlineSongInfo":false}),out.join("Data"),out.join("LocalAppData"),out.join("Logs"));
 let result=(||->Result<Value,String>{let first=wait(&b,"晴天",60.,180)?;timeline(120,269).map_err(|e|e.to_string())?;let seek=wait(&b,"晴天",120.,5)?;if first["frame"]["currentLine"]==seek["frame"]["currentLine"]{return Err("online timeline failed to follow fixture seek".into())}music.SetTitle(&HSTRING::from("Blinding Lights")).map_err(|e|e.to_string())?;music.SetArtist(&HSTRING::from("The Weeknd")).map_err(|e|e.to_string())?;display.Update().map_err(|e|e.to_string())?;timeline(60,200).map_err(|e|e.to_string())?;let changed=wait(&b,"Blinding Lights",60.,180)?;Ok(json!({"success":true,"first":first,"seek":seek,"changed":changed,"userPlayerCommands":0,"localFolders":[],"source":"isolated SMTC fixture, production modules and direct HTTP"}))})();b.close();match result{Ok(report)=>{std::fs::write(out.join("report.json"),serde_json::to_vec_pretty(&report)?)?;println!("PASS: SMTC -> media backend -> lyric DLL -> Go worker -> direct online lyric -> display, seek and track change");Ok(())},Err(e)=>{std::fs::write(out.join("report.json"),serde_json::to_vec_pretty(&json!({"success":false,"error":e}))?)?;Err(e.into())}}
}}
